/**
 * @method
 * @name sangjangJooSik
 * @description sangjang Joo Sik 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sangjangJooSik = async function () {
    const form = (document.preListForm || { elements: [] });
    if (form.gongMo !== 'undefined') {
        if ($c.util.getComponent("dma_sangjangJooSikReq").get("gongMo") === 'Y') {
            $c.util.getComponent("dma_sangjangJooSikReq").set("listInvstgBzTpCd", '140');
        } else {
            $c.util.getComponent("dma_sangjangJooSikReq").set("listInvstgBzTpCd", '120');
        }
    }
    if ($c.util.getComponent("dma_sangjangJooSikReq").get("page") === '00' || $c.util.getComponent("dma_sangjangJooSikReq").get("page") === '99' || $c.util.getComponent("dma_sangjangJooSikReq").get("page") === '98') {
        if ($c.util.getComponent("dma_sangjangJooSikReq").get("mode") === 'new') {
            await $c.win.alert("모든 메뉴는 '기업개요'작성 이후에 작성이 가능합니다.");
        } else {
            if (await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) {
                $c.util.getComponent("dma_sangjangJooSikReq").set("method", "searchListShrs");
                $c.util.getComponent("dma_sangjangJooSikReq").set("gongMo", "N");
                $c.util.getComponent("dma_sangjangJooSikReq").set("bzCd", "3_1");
                $c.util.getComponent("dma_sangjangJooSikReq").set("page", "50");
                { const __nr = await scwin.tx_sangjangJooSik(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil55200/jldfil55200.xml", { "listInvstgBzTpCd": '140', "method": "searchListShrs", "gongMo": "N", "bzCd": "3_1", "page": "50" }); } };
            }
        }
    } else {
        if (await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) {
            $c.util.getComponent("dma_sangjangJooSikReq").set("method", "searchListShrs");
            $c.util.getComponent("dma_sangjangJooSikReq").set("gongMo", "N");
            $c.util.getComponent("dma_sangjangJooSikReq").set("bzCd", "3_1");
            $c.util.getComponent("dma_sangjangJooSikReq").set("page", "50");
            { const __nr = await scwin.tx_sangjangJooSik(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil55200/jldfil55200.xml", { "listInvstgBzTpCd": '140', "method": "searchListShrs", "gongMo": "N", "bzCd": "3_1", "page": "50" }); } };
        }
    }
};

/**
 * @method
