/**
 * @method
 * @name prtDepo
 * @description prt Depo 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prtDepo = async function (bzProcsNo, ldMktTpCd, tp) {
    if ($c.util.getComponent("dma_sangjangJooSikReq").get("page") === '00' || $c.util.getComponent("dma_sangjangJooSikReq").get("page") === '99' || $c.util.getComponent("dma_sangjangJooSikReq").get("page") === '98') {
        if ($c.util.getComponent("dma_sangjangJooSikReq").get("mode") === 'new') {
            await $c.win.alert("모든 메뉴는 '기업개요'작성 이후에 작성이 가능합니다.");
        } else {
            await scwin.doPrtDepo(bzProcsNo, ldMktTpCd, tp);
        }
    } else {
        await scwin.doPrtDepo(bzProcsNo, ldMktTpCd, tp);
    }
};

/**
 * @method
 * @name doPrtDepo
 * @description do Prt Depo 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {*} tp tp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doPrtDepo = async function (bzProcsNo, ldMktTpCd, tp) {
    const frm = (document.preListForm || { elements: [] });
    if (await $c.win.confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) {
        frm.action = '/listInvstg/listPrePrtDepo.do';
        $c.util.getComponent("dma_sangjangJooSikReq").set("method", 'getlistPrePrtDepo');
        $c.util.getComponent("dma_sangjangJooSikReq").set("page", '40');
        $c.util.getComponent('dma_doPrtDepoReq').set('bzProcsNo', "" + bzProcsNo);
        $c.util.getComponent('dma_doPrtDepoReq').set('ldMktTpCd', "" + ldMktTpCd);
        if (frm.gongMo !== 'undefined') {
            if ($c.util.getComponent("dma_sangjangJooSikReq").get("gongMo") === 'Y') {
                $c.util.getComponent("dma_sangjangJooSikReq").set("listInvstgBzTpCd", '140');
            } else {
                $c.util.getComponent("dma_sangjangJooSikReq").set("listInvstgBzTpCd", '120');
            }
        }
        $c.util.getComponent('dma_doPrtDepoReq').set('view', tp);
        const nr = await scwin.tx_doPrtDepo();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil51090/jldfil51090.xml", { "method": 'getlistPrePrtDepo', "page": '40', "listInvstgBzTpCd": '140', "view": tp });
        }
    }
};
